17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.ArrayList;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.regex.Pattern;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
35	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
36	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
37	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.security.access.prepost.PreAuthorize;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.RequestMapping;
49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    private final ClinicService clinicService;
64	
65	    private final OwnerMapper ownerMapper;
66	
67	    private final PetMapper petMapper;
68	
69	    private final VisitMapper visitMapper;
70	
71	    public OwnerRestControllerV1(ClinicService clinicService,
72	                                 OwnerMapper ownerMapper,
73	                                 PetMapper petMapper,
74	                                 VisitMapper visitMapper) {
75	        this.clinicService = clinicService;
76	        this.ownerMapper = ownerMapper;
77	        this.petMapper = petMapper;
78	        this.visitMapper = visitMapper;
79	    }
80	
81	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
82	    @Override
83	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
84	        Collection<Owner> owners;
85	        if (lastName != null) {
86	            owners = this.clinicService.findOwnerByLastName(lastName);
87	        } else {
88	            owners = this.clinicService.findAllOwners();
89	        }
90	        if (owners.isEmpty()) {
91	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
92	        }
93	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
99	        Owner owner = this.clinicService.findOwnerById(ownerId);
100	        if (owner == null) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
104	    }
105	
106	    /**
107	     * Rejects an owner payload that is missing or blank in any of the required fields
108	     * (firstName, lastName, address, city, telephone). Bean Validation on the request body
109	     * already rejects {@code null} values and empty strings, but treats a whitespace-only
110	     * value as present; this guard closes that gap so a blank in any required field is
111	     * reported. The thrown exception is translated to a 400 whose {@code errors} array lists
112	     * the name of each offending field.
113	     */
114	    private void rejectMissingOrBlankFields(OwnerFieldsDto ownerFieldsDto) {
115	        List<String> missing = new ArrayList<>();
116	        if (isBlank(ownerFieldsDto.getFirstName())) {
117	            missing.add("firstName");
118	        }
119	        if (isBlank(ownerFieldsDto.getLastName())) {
120	            missing.add("lastName");
121	        }
122	        if (isBlank(ownerFieldsDto.getAddress())) {
123	            missing.add("address");
124	        }
125	        if (isBlank(ownerFieldsDto.getCity())) {
126	            missing.add("city");
127	        }
128	        if (isBlank(ownerFieldsDto.getTelephone())) {
129	            missing.add("telephone");
130	        }
131	        if (!missing.isEmpty()) {
132	            throw new MissingOwnerFieldsException(missing);
133	        }
134	    }
135	
136	    private static boolean isBlank(String value) {
137	        return value == null || value.isBlank();
138	    }
139	
140	    /**
141	     * Normalizes an owner's telephone on create by stripping every non-digit character and
142	     * requiring exactly ten digits to remain. The stripped, digits-only value is what gets
143	     * stored and returned. A value that does not reduce to exactly ten digits is rejected via
144	     * {@link InvalidTelephoneException}, which the exception handler translates to a 400.
145	     */
146	    private static String normalizeTelephone(String telephone) {
147	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
148	        if (digits.length() != 10) {
149	            throw new InvalidTelephoneException(telephone);
150	        }
151	        return digits;
152	    }
153	
154	    /**
155	     * A pragmatic syntactic email check: a non-empty local part, an {@code @}, and a domain that
156	     * carries at least one dot, with no whitespace anywhere. Deliberately permissive — it accepts
157	     * ordinary addresses while rejecting obvious non-addresses such as one lacking an {@code @}.
158	     */
159	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
160	
161	    /**
162	     * Normalizes an optional owner email. A {@code null} email is left as-is (the field is
163	     * optional). When present it must be a syntactically valid address; a valid value is
164	     * lower-cased so it is stored and returned in canonical form. An invalid value is rejected via
165	     * {@link InvalidEmailException}, which the exception handler translates to a 400.
166	     */
167	    private static String normalizeEmail(String email) {
168	        if (email == null) {
169	            return null;
170	        }
171	        if (!EMAIL_PATTERN.matcher(email).matches()) {
172	            throw new InvalidEmailException(email);
173	        }
174	        return email.toLowerCase(Locale.ROOT);
175	    }
176	
177	    /**
178	     * Rejects a create whose normalized telephone is already used by another owner. Each
179	     * existing owner's stored telephone is reduced to digits the same way {@code normalize}
180	     * does, so the comparison is on the canonical, digits-only form. A match is reported via
181	     * {@link DuplicateTelephoneException}, which the exception handler translates to a 409.
182	     */
183	    private void rejectDuplicateTelephone(String normalizedTelephone) {
184	        for (Owner existing : this.clinicService.findAllOwners()) {
185	            String existingDigits = existing.getTelephone() == null
186	                ? "" : existing.getTelephone().replaceAll("\\D", "");
187	            if (normalizedTelephone.equals(existingDigits)) {
188	                throw new DuplicateTelephoneException(normalizedTelephone);
189	            }
190	        }
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
196	        rejectMissingOrBlankFields(ownerFieldsDto);
197	        HttpHeaders headers = new HttpHeaders();
198	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
199	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
200	        rejectDuplicateTelephone(normalizedTelephone);
201	        owner.setTelephone(normalizedTelephone);
202	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
203	        this.clinicService.saveOwner(owner);
204	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
205	        headers.setLocation(UriComponentsBuilder.newInstance()
206	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
207	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
208	    }
209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Override
212	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
213	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
214	        if (currentOwner == null) {
215	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
216	        }
217	        currentOwner.setAddress(ownerFieldsDto.getAddress());
218	        currentOwner.setCity(ownerFieldsDto.getCity());
219	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
220	        currentOwner.setLastName(ownerFieldsDto.getLastName());
221	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
222	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
223	        this.clinicService.saveOwner(currentOwner);
224	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
225	    }
226	
227	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
228	    @Transactional
229	    @Override
230	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
231	        Owner owner = this.clinicService.findOwnerById(ownerId);
232	        if (owner == null) {
233	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
234	        }
235	        this.clinicService.deleteOwner(owner);
236	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
237	    }
238	
239	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
240	    @Override
241	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
242	        Owner owner = this.clinicService.findOwnerById(ownerId);
243	        if (owner == null) {
244	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
245	        }
246	        HttpHeaders headers = new HttpHeaders();
247	        Pet pet = petMapper.toPet(petFieldsDto);
248	        owner.setId(ownerId);
249	        pet.setOwner(owner);
